# -*- coding: utf-8 -*-
# _opn_ai_06.py  卷六 观点层源数据

RECORDS = [{'item_id': '06-002', 'topic': '世有受人恩而反败者', 'stance': '叹', 'who': '顾起元', 'first_person': '顾起元', 'detail': '叹金白屿济人三事而盗尚知报恩：世有生平受人恩，临事而反面，且下石焉者比比然也，使此盗闻之，其不以为非人也与哉！'}, {'item_id': '06-003', 'topic': '弘治策冒同语而登高第', 'stance': '考', 'who': '丹丘王先生', 'first_person': '顾起元', 'detail': '吴大有乡会试五策中三道策冒俱云“三问而三不知，君子以为深知”而主司皆列高等；丹丘王先生曰弘治中风气淳庞，如此者人不以为诽，使在嘉靖中必以是为关节矣。'}, {'item_id': '06-005', 'topic': '好诙谐致祸', 'stance': '戒', 'who': '顾起元', 'first_person': '顾起元', 'detail': '黄谦以性好诙谐戏语结怨，后为旧怨者所构陷削籍，遂离此祸；陈太史《善谑录》常记之，往往令人绝倒。'}, {'item_id': '06-007', 'topic': '科举防弊之严', 'stance': '评', 'who': '顾起元', 'first_person': '顾起元', 'detail': '刘自强操持严峻人不敢干以私：拒南太宰请托拳落隶齿，发顶名替考之首，冒籍诈伪者闻风敛迹遁去，送院者仅八十八人；督学耿定向不得已汰其八人，曰例不可废也。'}, {'item_id': '06-010', 'topic': '知音难遇', 'stance': '叹', 'who': '顾起元', 'first_person': '顾起元', 'detail': '叹陈大声以精音律为教坊子弟称“乐王”，武夫伶人犹知好其知音者，今安在乎哉；又叹友人陈荩卿亦工度曲与二公相上下，而穷愁不称其意气，所著多冒它人姓氏，甘为床头捉刀人以死，可叹也。'}, {'item_id': '06-011', 'topic': '二公词场伯仲', 'stance': '评', 'who': '顾起元', 'first_person': '顾起元', 'detail': '陈秋碧与徐髯仙《咏四景联句》词绵丽宛折曲尽个中情景，如二公者故词场之伯仲也。'}, {'item_id': '06-012', 'topic': '雉山咏牡丹词', 'stance': '评', 'who': '顾起元', 'first_person': '顾起元', 'detail': '邢雉山先生填词多不传，曾见其《咏牡丹》一调音节谐畅词意艳美，真作家也。'}, {'item_id': '06-013', 'topic': '二公以不良死', 'stance': '悼', 'who': '顾起元', 'first_person': '顾起元', 'detail': '孙炎与金陵夏煜皆有诗名，负诗名挟意气而皆以不良死：炎官总制处州苗将叛死之，煜为佥事犯法被投于江，可悼也。'}, {'item_id': '06-014', 'topic': '作文避讳', 'stance': '考', 'who': '顾起元', 'first_person': '顾起元', 'detail': '倪文毅公草于公《神道碑》因于公名与先考同，未敢以私故阙而不书，盖公之所关者大也临文悚然；碑云“岳在里姻之末”，以于阜乃于公之孙婿故；此可为作文避讳者增一事例。'}, {'item_id': '06-015', 'topic': '内乱未成者不当论死', 'stance': '辩', 'who': '夏时正', 'first_person': '顾起元', 'detail': '夏时正拟刑部狱囚欲乱其子妇而未成者流罪，引经据律奏辩数千言：谓《春秋》无将将则必诛，今律刦囚者斩不须得囚，此则不分成未成也；内乱已成者妇行已污伦理已渎故不得已刑之，未成者妇行未亏伦理犹未坏，罪止于流不忍加之死；此圣祖好生之德制律之微意，永乐宣德间未成者犹多谪戍，今安得一切论死乎。'}, {'item_id': '06-017', 'topic': '五堰废置之失', 'stance': '考', 'who': '顾起元', 'first_person': '顾起元', 'detail': '述伍余福《三吴水利论》并苏轼奏议：古者宣歙金陵九阳江诸水皆入芜湖以五堰障之，杨行密作五堰以为拖舸馈粮之计；后贩簰木者以五堰为阻遂废去，而东西二坝列焉，诸水多入荆溪，间有入芜湖者亦西北之源而非东南之势。'}, {'item_id': '06-019', 'topic': '漕运十总之制', 'stance': '考', 'who': '顾起元', 'first_person': '顾起元', 'detail': '嘉靖间天下十总每年过淮船一万二千一百四十三只：南京总、中都留守总、浙江总、江北直隶总、江南直隶总、江西总、湖广总、遮洋总等；迄今则十三总，事体亦多所更置。'}, {'item_id': '06-021', 'topic': '徐居云墓铭', 'stance': '评', 'who': '皇甫司勋', 'first_person': '顾起元', 'detail': '徐京中山王七世孙与诸公为词翰友赋诗唱和；皇甫司勋参定其所著集序之，既卒又为之墓铭，词甚凄折。'}, {'item_id': '06-022', 'topic': '金陵尼中有如此人', 'stance': '叹', 'who': '顾起元', 'first_person': '顾起元', 'detail': '述谢小娥梦得隐语、李公佐解之、佣身复雠、受戒为尼之事，叹金陵尼中乃有如此人。'}, {'item_id': '06-023', 'topic': '好夸之戒', 'stance': '戒', 'who': '顾起元', 'first_person': '顾起元', 'detail': '张允怀以写梅游苏杭，夜泊金山月明风静出金银器饮酒吹箫自娱为盗所窥被歼，其酒器皆铜而涂金银者也，此可为好夸之戒。'}, {'item_id': '06-024', 'topic': '君臣相得之礼', 'stance': '评', 'who': '顾起元', 'first_person': '顾起元', 'detail': '景泰帝亲临文华殿听倪谦吕原讲书，命二人以侍讲学士兼中允；二人改坐于旁不以君父之坐自居，上曰如是乎，其后至馆中惟立谈或东西行不复坐；倪公后以光学主顺天试为门生所讦陷谪戍，复起官礼部尚书。'}, {'item_id': '06-026', 'topic': '良贱之分', 'stance': '叹', 'who': '顾起元', 'first_person': '顾起元', 'detail': '记太祖立富乐院定官妓服制、禁文武官及舍人入院等事，叹彼时良贱之分如此，今澜倒尽矣。'}, {'item_id': '06-027', 'topic': '勋卫之所由始', 'stance': '考', 'who': '顾起元', 'first_person': '顾起元', 'detail': '太祖立君子舍人二卫为心腹，选文官子侄居君子卫武官子侄居舍人卫，昼侍从夜直宿更番；按即此勋卫之所由始也，后不复用文官子侄矣。'}, {'item_id': '06-029', 'topic': '成弘间南都人物之盛', 'stance': '评', 'who': '叶盛', 'first_person': '顾起元', 'detail': '叶文庄《水东日记》历评南都勋旧贤如襄城伯李公、通材重望如少保黄公、学行老成如都御史吴公等，谓如诸公者今何可多得；由此可以想见成弘间南都宦籍之盛。'}, {'item_id': '06-030', 'topic': '群鸦绕阙之兆', 'stance': '考', 'who': '顾起元', 'first_person': '顾起元', 'detail': '献皇帝之国舟泊龙江关乌鸦万数集江柳向舟鸣噪，李空同以为世宗中兴之兆；弘治初侍朝钟鼓鸣则乌鸦万数集龙楼，正德间不复见；万历间每日黎明群鸦盘旋飞绕五凤楼久之方散，时人谓之鸦朝；堪舆家又有鸟朝牛朝鱼朝之说。'}, {'item_id': '06-036', 'topic': '中西画法之别', 'stance': '评', 'who': '利玛窦', 'first_person': '利玛窦', 'detail': '利玛窦论画：中国画但画阳不画阴，故看之人面躯正平无凹凸相；吾国画兼阴与阳写之，故面有高下而手臂皆轮圆；凡人之面正迎阳则皆明而白，侧立则向明一边白，不向明一边眼耳鼻口凹处皆有暗相，吾国之写像者解此法用之故能与生人亡异。'}, {'item_id': '06-036', 'topic': '婆罗门算法', 'stance': '考', 'who': '顾起元', 'first_person': '顾起元', 'detail': '利玛窦所著《天主实义》及《十论》多新警，独于天文算法为尤精；郑夹漈《艺文略》载有婆罗门算法者，疑是此术，士大夫颇有传而习之者。'}, {'item_id': '06-039', 'topic': '文中有画', 'stance': '评', 'who': '顾起元', 'first_person': '顾起元', 'detail': '景伯时太史游绎山记文不数百言而宛然如觏，状石之方圆平欹各各异象，如屋覆如偃盖如走丸如斧劈等，绝顶一丸高数十丈欹置平石有可转而不转之势，可谓文中有画矣。'}, {'item_id': '06-040', 'topic': '好石亦风流罪过', 'stance': '劝', 'who': '顾起元', 'first_person': '顾起元', 'detail': '陈玉叔好石如米襄阳之下拜：取人英石系轿杠而归，购凤台园大石舟载至马当山下簸入江；后以省臣论归，顾起元解之曰据所云云古人以为佳话，即不然亦风流罪过耳，且升沉常事何足芥蒂邪，先生大笑抗手而别。'}, {'item_id': '06-042', 'topic': '弇州评诗之苛', 'stance': '辩', 'who': '顾起元', 'first_person': '顾起元', 'detail': '弇州《明诗评》初评孙炎汤胤勣王韦刘麟顾璘诸金陵诗人甚当，其后评汤公让如淮阳少年王钦珮如小女儿带花等语涉太苛；噫，千载而下，其当自有定论。'}, {'item_id': '06-045', 'topic': '金陵人物志传本之难', 'stance': '叹', 'who': '顾起元', 'first_person': '顾起元', 'detail': '盛仲交手题陈中丞《人物志》抄本叙其借录辗转之难，欲并《金陵世纪》刊之传布四方；至万历乙卯已六十四年，伯年（盛敏耕）示此书在乙未丙申间亦二十余年，伯年下世又屡易岁华，此志恐世鲜传本，偶检笥得之于伯年有人琴之感，因掇而笔之。'}, {'item_id': '06-046', 'topic': '赤松山农之高', 'stance': '评', 'who': '顾起元', 'first_person': '顾起元', 'detail': '金元玉游浙之赤松山爱其佳因以赤松山农自号，居常遐视清啸人莫能窥，处己接物高简粹白，王公贵人雅相倾慕非先施未尝一登其门，太宰青溪倪公拟荐未果，弘治辛酉卒；其标韵如此盖亦高士，王子新作诗嘲之有“内桥写铭旌”之语。'}, {'item_id': '06-047', 'topic': '犯而不校', 'stance': '评', 'who': '顾起元', 'first_person': '顾起元', 'detail': '梁端肃公立身清峻而弘人之度未尝不优：为浙江方伯执法不挠御史摭其十恶奏之，铨曹廉其非实量移云南，公居之恬然曰御史言是邪谴死无恨无然自有公论在矣；尝曰犯而不校某敢当之；为都御史里居乘小舆，御史前驺呵之，知为梁某亟造其庭请罪，公笑曰何罪之有第骢马行人人敛手避，小舆而敢突之必有以，可勿问耳，揖之而出。'}, {'item_id': '06-049', 'topic': '蒋康之之夜歌', 'stance': '评', 'who': '顾起元', 'first_person': '顾起元', 'detail': '蒋康之金陵人其音属宫如玉磬之击明堂温润可爱；癸未春度南康夜泊彭蠡之南扣舷而歌“江水澄澄江月明”之词，湖上之民莫不拥衾而听，推窗出户见听者杂迨于岸，少焉满江如有长叹之声，自此声誉愈远。'}, {'item_id': '06-052', 'topic': '十四楼与富乐院', 'stance': '考', 'who': '顾起元', 'first_person': '顾起元', 'detail': '国初市之楼有十六以处官妓，《南畿志》止十四；李泰集句咏十六楼中有清江石城二楼，晏振之诗又有“花月春江十四楼”之句，知相沿已久；今独南市楼存，而北市在乾道桥东北似今之猪市，疑刘辰《国初事迹》所记富乐院即此地也。'}, {'item_id': '06-054', 'topic': '江宁县牛形之说', 'stance': '考', 'who': '顾起元', 'first_person': '顾起元', 'detail': '府治洪武初自集庆路徙治古锦绣坊大军库地；上元县唐置永寿宫东徙凤台山西宋徙白下桥，国朝在府治东北昇平桥西；江宁县古去城七十里即今江宁镇，南唐迁北门清化坊元徙越台侧国初徙集庆路治；县无大门前临街有二亭子，俗谓其地势为牛形，肤施杨令建屏墙竟病头痛，撤而瘳。'}, {'item_id': '06-055', 'topic': '金润之清福', 'stance': '评', 'who': '顾起元', 'first_person': '顾起元', 'detail': '金润十二能赋诗，以乡贡授兵部司务擢南安知府，政暇弹琴写画赋诗；以子侍郎绅贵乞休家居，手制床几十事号洞天十友，风神如仙，寿九十赋诗一章而逝。'}, {'item_id': '06-056', 'topic': '沈钟日赋诗', 'stance': '评', 'who': '顾起元', 'first_person': '顾起元', 'detail': '沈仲律举天顺庚辰进士官副宪致仕，日赋诗平生万首，文字之外世事无所闻；后以子宝迎养江夏，年八十余而卒，有《休斋稿》。'}, {'item_id': '06-057', 'topic': '丁镛清逸', 'stance': '评', 'who': '顾起元', 'first_person': '顾起元', 'detail': '丁公镛举成化己丑进士官兴化守致仕，性嗜文学耽诗尤爱佳山水多宿山寺，盖清逸之士也；有《石厓集》今亦不甚传。'}, {'item_id': '06-058', 'topic': '唐祝二赋优劣', 'stance': '辩', 'who': '何良俊、顾璘', 'first_person': '顾起元', 'detail': '祝支山《观云赋》东桥甚重之，何柘湖皆不以为佳，东桥谓烟花洞天自是风流佳话不必绳以礼法；柘湖又言唐六如《广志赋》托意既高遣辞甚古而唐集不载，唐才情绝胜失意后所作多凄咽感叹之旨，诗赋胜于支山，画高出沈石田文衡山之上，与祝才字并雄可以上掩前古。'}, {'item_id': '06-059', 'topic': '学杜之非', 'stance': '辩', 'who': '顾璘', 'first_person': '顾起元', 'detail': '东桥先生论诗：李空同言作诗必须学杜，诗至杜子美如至圆不能加规至方不能加矩，此空同之过言也；夫规矩方圆之至故匠者皆用之，杜亦在规矩中耳，若必要学杜只是学某匠，何得就以子美为规矩邪；何大复所谓舍筏登岸亦是欺人；又尝语人曰何大复之诗虽则稍俊，终是空同多一臂力。'}, {'item_id': '06-060', 'topic': '徐髯仙其人足重', 'stance': '评', 'who': '何良俊', 'first_person': '顾起元', 'detail': '何柘湖云徐髯仙豪爽逸宕人也，数游狭邪，其所填南北词皆入律，衡山题画寄之谓“乐府新传桃叶句，彩毫遍写薛涛笺，老我别来忘不得，令人常想秣陵烟”，盖其人诚足重也；晚遇武宗幸其家挟以北行赐飞鱼服，然杂在佞幸中公非所志竟谢归。'}, {'item_id': '06-062', 'topic': '松坞高士图之神', 'stance': '评', 'who': '何良俊', 'first_person': '顾起元', 'detail': '何柘湖言王子新《松坞高士图》无画家蹊径，疏秀可爱，盖其风韵骨力出于天成也；顾起元又藏其墨梅扇面，后小楷书一绝句，字法智永而遒劲过之。'}]
